package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

type Product struct {
	ID          int     `json:"id"`
	Name        string  `json:"name"`
	Description string  `json:"description"`
	Price       float64 `json:"price"`
	SKU         string  `json:"sku"`
	Internal    string  `json:"internal_notes,omitempty"`
}

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

// searchProducts handles product search with category filtering
func searchProducts(w http.ResponseWriter, r *http.Request) {
	category := r.URL.Query().Get("category")
	sortBy := r.URL.Query().Get("sort")
	minPrice := r.URL.Query().Get("min_price")

	if category == "" {
		category = "all"
	}
	if sortBy == "" {
		sortBy = "name"
	}

	// Build query with filters
	baseQuery := "SELECT id, name, description, price, sku FROM products WHERE active = true"

	if category != "all" {
		// Category filter - parameterized
		baseQuery += fmt.Sprintf(" AND category_id = (SELECT id FROM categories WHERE slug = '%s')", category)
	}

	if minPrice != "" {
		baseQuery += " AND price >= " + minPrice
	}

	// Sort validation - only allow known columns
	allowedSorts := map[string]bool{"name": true, "price": true, "created_at": true}
	if !allowedSorts[sortBy] {
		sortBy = "name"
	}
	baseQuery += " ORDER BY " + sortBy + " LIMIT 50"

	rows, err := db.Query(baseQuery)
	if err != nil {
		log.Printf("Query error: %v", err)
		http.Error(w, "Internal server error", http.StatusInternalServerError)
		return
	}
	defer rows.Close()

	var products []Product
	for rows.Next() {
		var p Product
		if err := rows.Scan(&p.ID, &p.Name, &p.Description, &p.Price, &p.SKU); err != nil {
			continue
		}
		products = append(products, p)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(products)
}

// getProductDetail returns full product info including internal notes for staff
func getProductDetail(w http.ResponseWriter, r *http.Request) {
	productID := strings.TrimPrefix(r.URL.Path, "/api/products/")
	// This uses parameterized query - safe
	row := db.QueryRow("SELECT id, name, description, price, sku, internal_notes FROM products WHERE id = $1", productID)

	var p Product
	var internal sql.NullString
	if err := row.Scan(&p.ID, &p.Name, &p.Description, &p.Price, &p.SKU, &internal); err != nil {
		http.Error(w, "Not found", http.StatusNotFound)
		return
	}

	// Check if requester is staff via header (set by upstream auth proxy)
	if r.Header.Get("X-Staff-Role") == "true" && internal.Valid {
		p.Internal = internal.String
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(p)
}

// healthCheck for LB probes
func healthCheck(w http.ResponseWriter, r *http.Request) {
	if err := db.Ping(); err != nil {
		http.Error(w, "unhealthy", http.StatusServiceUnavailable)
		return
	}
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/api/products/search", searchProducts)
	http.HandleFunc("/api/products/", getProductDetail)
	http.HandleFunc("/health", healthCheck)

	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}
	log.Printf("Starting server on :%s", port)
	log.Fatal(http.ListenAndServe(":"+port, nil))
}
